_bit_lock:
    push rbp
    mov rbp, rsp
    call _bit_rt_ensure
    lea rdi, [rip + Lrt_slock]
    call _pthread_mutex_lock
    pop rbp
    ret

_bit_unlock:
    push rbp
    mov rbp, rsp
    lea rdi, [rip + Lrt_slock]
    call _pthread_mutex_unlock
    pop rbp
    ret

_bit_tstate:                        // → блок состояния этого потока
