    mov rbp, rsp
    push rbx
    sub rsp, 8
    call _bit_rt_ensure
    mov rdi, [rip + Lrt_tkey]
    call _pthread_getspecific
    test rax, rax
    jnz 9f
    mov edi, 64
    call _bit_alloc
    mov rbx, rax
    mov rdi, rax
    xor esi, esi
    mov edx, 64
    call _memset
